<script setup>
const{data,refresh}=await useFetch('/api/tasks');const modal=ref(false);const newTitle=ref('');const mobile=ref(false);const statuses=['To do','In progress','Done'];const tasks=computed(()=>data.value?.tasks||[]);const grouped=status=>tasks.value.filter(t=>t.status===status)
async function add(){await $fetch('/api/tasks',{method:'POST',body:{title:newTitle.value}});newTitle.value='';modal.value=false;await refresh()}
async function move(task){const index=statuses.indexOf(task.status);await $fetch(`/api/tasks/${task.id}`,{method:'PATCH',body:{status:statuses[(index+1)%3]}});await refresh()}
</script>
<template><main class="dash-page"><aside class="dash-side glass" :class="{open:mobile}"><NuxtLink class="brand" to="/"><i>F</i> FlowPilot</NuxtLink><small>WORKSPACE</small><button class="workspace"><span>BP</span>Bright Projects⌄</button><nav><a class="active">⌂ Overview</a><a>▦ My tasks <i>4</i></a><a>◎ Updates</a><a>◇ People</a></nav><small>PROJECTS</small><nav><a><b class="dot purple"></b>Website launch</a><a><b class="dot cyan"></b>Growth sprint</a><a><b class="dot lime"></b>Customer portal</a></nav><div class="user"><span>AN</span><div><b>Alex N.</b><small>Founder workspace</small></div></div></aside>
<section class="dash-content"><header><button class="mobile-menu" @click="mobile=!mobile">☰</button><div><p>PROJECT / WEBSITE LAUNCH</p><h1>Good morning, Alex.</h1></div><div><button class="search">⌕ Search</button><button class="solid" @click="modal=true">+ New task</button></div></header><div class="stats"><article class="glass"><span>PROGRESS</span><b>68%</b><div><i></i></div><small>12 of 18 tasks complete</small></article><article class="glass"><span>THIS WEEK</span><b>8</b><small>tasks completed <em>↗ 24%</em></small></article><article class="glass"><span>TEAM FOCUS</span><b>4.2</b><small>average priorities / person</small></article><article class="glass"><span>RISK</span><b class="good">Low</b><small>No blocked priorities</small></article></div><div class="board-head"><div><h2>Website launch</h2><span>Sample project</span></div><div><button>Filter</button><button>•••</button></div></div><div class="task-board"><div v-for="status in statuses" :key="status" class="column"><div class="column-head"><b>{{status}}</b><span>{{grouped(status).length}}</span></div><article v-for="task in grouped(status)" :key="task.id" class="task glass" @click="move(task)"><div><span :class="['priority',task.priority.toLowerCase()]">{{task.priority}}</span><small>{{task.due}}</small></div><h3>{{task.title}}</h3><footer><span>{{task.assignee}}</span><small>Click to move →</small></footer></article><button class="add-inline" @click="modal=true">+ Add task</button></div></div></section><div v-if="modal" class="overlay" @click="modal=false"></div><div v-if="modal" class="task-modal glass"><button @click="modal=false">×</button><p class="eyebrow">NEW PRIORITY</p><h2>Add a task</h2><label>What needs to happen?<input v-model="newTitle" autofocus placeholder="e.g. Review launch email"></label><button class="solid full" :disabled="!newTitle" @click="add">Create task</button><small>Demo note: click any task card to move it to the next column.</small></div></main></template>
